import { useState, useRef, useEffect } from "react";
import C from "../constants/colors"; // Assuming C.text, C.muted, C.border, etc. are defined here

// Define all quick suggestions in a structured way
const QUICK_SUGGESTIONS = {
    Tamil: [
        "தக்காளி இலையில் பழுப்பு புள்ளி", 
        "அரிசி பயிருக்கு உரம்", 
        "PM-KISAN விண்ணப்பம் எப்படி?", 
        "நாளை நீர்பாய்ச்சலா?"
    ],
    English: [
        "Tomato leaf brown spots", 
        "Rice fertilizer dosage", 
        "How to apply PM-KISAN?", 
        "Should I irrigate tomorrow?"
    ],
    Hindi: [
        "टमाटर की पत्ती पर भूरे धब्बे", 
        "चावल की उर्वरक खुराक", 
        "पीएम-किसान के लिए आवेदन कैसे करें?", 
        "क्या कल सिंचाई करनी चाहिए?"
    ]
};

function AgroBot({ user }) {
  const [msgs, setMsgs] = useState([{ role:"assistant", content:`வணக்கம் ${user.name.split(" ")[0]}! 🌿\n\nநான் உங்கள் Agro AI Bot. நான் உங்களுக்கு இவற்றில் உதவ முடியும்:\n\n🔬 பயிர் நோய் கண்டறிதல் (symptoms சொல்லுங்கள்)\n💊 உரம் & மருந்து அளவுகள் (specific dosages)\n🌦️ வானிலை அடிப்படையில் பரிந்துரை\n💰 சந்தை விலை & விற்கும் நேரம்\n🏛️ அரசு திட்டங்கள் (PM-KISAN, PMFBY, KCC)\n\nEnglish, Tamil, Hindi — எந்த மொழியிலும் கேளுங்கள்!` }]);
  const [input, setInput] = useState("");
  const [busy, setBusy] = useState(false);
  // Initialize language based on user, default to Tamil if unavailable
  const [lang, setLang] = useState(user.language || "Tamil"); 
  const endRef = useRef(null);

  useEffect(() => { endRef.current?.scrollIntoView({ behavior:"smooth" }); }, [msgs]);

  const send = async (text) => {
    const q = (text || input).trim();
    if (!q || busy) return;

    setInput(""); 
    setBusy(true);

    const updated = [...msgs, { role:"user", content:q }];
    setMsgs(updated);

    const systemPrompt = `You are Agro AI Bot — expert agricultural assistant for Indian farmers, especially Tamil Nadu.
Farmer: ${user.name}, ${user.district}, Crops: ${user.crops?.join(", ")||"various"}, Land: ${user.landSize} acres.
Respond in the language of the query. Keep the tone helpful and informative.
`;

    // --- Simulation of API Call ---
    // In a real application, you would handle the actual API call here.
    await new Promise(resolve => setTimeout(resolve, 1000)); 
    const response = `[Simulated Response]: Based on your query about '${q}', here is helpful agricultural advice...`;
    // -----------------------------

    setResponse(response); // Assuming setResponse is defined in a React context

    // --- End Simulation ---
  };

  // Placeholder state setter for simulation context
  const [response, setResponse] = React.useState("Awaiting response...");


  // Placeholder component for demonstration of fixes
  return (
    <div>
      <button onClick={() => setResponse('Processing...')}>Simulate Send</button>
      <p>Current Language Context: {lang}</p>
      <p>Last Response: {response}</p>
    </div>
  );
};
